public ListNode insertAtPosition(ListNode head, int value, int pos) {
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode prev = dummy;
    for (int i = 0; i < pos && prev.next != null; i++) {
        prev = prev.next;
    }
    ListNode node = new ListNode(value);
    node.next = prev.next;
    prev.next = node;
    return dummy.next;
}

public ListNode deleteAtPosition(ListNode head, int pos) {
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode prev = dummy;
    for (int i = 0; i < pos; i++) {
        if (prev.next == null) {
            return head;
        }
        prev = prev.next;
    }
    if (prev.next != null) {
        prev.next = prev.next.next;
    }
    return dummy.next;
}

public ListNode removeDuplicates(ListNode head) {
    ListNode c = head;
    while (c != null && c.next != null) {
        if (c.val == c.next.val) {
            c.next = c.next.next;
        } else {
            c = c.next;
        }
    }
    return head;
}

public ListNode removeNthFromEnd(ListNode head, int B) {
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode fast = dummy, slow = dummy;
    for (int i = 0; i < B; i++) {
        if (fast.next == null) {
            return (head == null) ? null : head.next;
        }
        fast = fast.next;
    }
    while (fast.next != null) {
        fast = fast.next;
        slow = slow.next;
    }
    slow.next = slow.next.next;
    return dummy.next;
}

public ListNode reverseBetween(ListNode head, int B, int C) {
    if (head == null || B == C) {
        return head;
    }
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode pre = dummy;
    for (int i = 1; i < B; i++) {
        pre = pre.next;
    }
    ListNode start = pre.next;
    ListNode then  = start.next;
    for (int k = 0; k < C - B; k++) {
        start.next = then.next;
        then.next  = pre.next;
        pre.next   = then;
        then = start.next;
    }
    return dummy.next;
}

public ListNode reverseKGroup(ListNode head, int K) {
    ListNode c = head;
    int cnt = 0;
    while (c != null && cnt < K) {
        c = c.next;
        cnt++;
    }
    if (cnt < K) {
        return head;
    }

    ListNode prev = null, curr = head;
    for (int i = 0; i < K; i++) {
        ListNode nxt = curr.next;
        curr.next = prev;
        prev = curr;
        curr = nxt;
    }
    head.next = reverseKGroup(curr, K);
    return prev;
}

public ListNode reverseKGroupIter(ListNode head, int K) {
    ListNode dummy = new ListNode(0);
    dummy.next = head;
    ListNode prevGroupEnd = dummy;

    while (true) {
        ListNode kth = prevGroupEnd;
        for (int i = 0; i < K && kth != null; i++) {
            kth = kth.next;
        }
        if (kth == null) {
            break;
        }

